def compute(vars):
    shares = vars["v1"]
    exercise_price = vars["v2"]
    proceeds = shares * exercise_price
    return {
        "value": proceeds,
        "trace": {
            "shares": shares,
            "exercise_price": exercise_price,
            "output_meta": {
                "currency": "USD",
                "scale": "ones",
                "unit": "dollars"
            }
        }
    }
